#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int earliestTime(std::vector<std::vector<int>>& tasks) {
        int best = INT_MAX;
        for (const auto& t : tasks) {
            best = std::min(best, t[0] + t[1]);
        }
        return best;
    }
};

class Solution {
    public int earliestTime(int[][] tasks) {
        int best = Integer.MAX_VALUE;
        for (int[] t : tasks) {
            best = Math.min(best, t[0] + t[1]);
        }
        return best;
    }
}

var earliestTime = function(tasks) {
    let best = Infinity;
    for (const [start, dur] of tasks) {
        const finish = start + dur;
        if (finish < best) best = finish;
    }
    return best;
};
